Create a guard struct that stores the original value and a mutable reference to restore it:

struct TempValueGuard<'a, T> {
    original: T,
    target: &'a mut T,
}

impl<'a, T: Clone> TempValueGuard<'a, T> {
    fn new(target: &'a mut T, temp_value: T) -> Self {
        let original = target.clone();
        *target = temp_value;
        TempValueGuard { original, target }
    }
}

impl<T> Drop for TempValueGuard<'_, T> {
    fn drop(&mut self) {
        *self.target = self.original.clone();
    }
}

// Usage:
let mut config = Config::default();
{
    let _guard = TempValueGuard::new(&mut config.debug_mode, true);
    // debug_mode is temporarily true
} // debug_mode automatically restored to original value

