```rust
enum TaskMessage {
    Execute(Task, oneshot::Sender<Result<TaskResult, TaskError>>),
    Status(oneshot::Sender<ActorStatus>),
    Shutdown
}

struct TaskActor {
    receiver: mpsc::Receiver<TaskMessage>,
    status: ActorStatus
}

impl TaskActor {
    async fn handle_message(&mut self, msg: TaskMessage) {
        match msg {
            TaskMessage::Execute(task, reply) => {
                let result = self.process_task(task).await;
                let _ = reply.send(result);
            }
            _ => {}
        }
    }
}
